mapper.select:
SELECT c.clothes_id, c.name, c.category, c.clo, CASE WHEN NULLIF(c.image_url, '') IS NOT NULL THEN CONCAT('/api/clothes/', c.clothes_id, '/photo') END AS image_url, c.storage_status, s.storage_location_id FROM ( SELECT clothes_id, user_id, name, category, clo, image_url, storage_status, storage_location_id, ROW_NUMBER() OVER ( PARTITION BY COALESCE(same_group_id, clothes_id) ORDER BY clothes_id DESC ) AS group_rank FROM clothes WHERE user_id = #{userId} AND deleted_at IS NULL
AND category = #{category,jdbcType=VARCHAR}
AND storage_status = #{storageStatus,jdbcType=VARCHAR}
) c LEFT JOIN storage_locations s ON s.storage_location_id = c.storage_location_id AND s.user_id = c.user_id AND s.deleted_at IS NULL WHERE c.group_rank = 1 ORDER BY c.clothes_id DESC
